def transform(grid):
    h,w=len(grid),len(grid[0])
    # Extract diagonal line colors by the invariant r+c (for the demonstrated
    # up-right tracks) and use the smallest repeating color word.
    tracks={}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v: tracks[r+c]=v
    # Convert colored track locations to a periodic word on the diagonal index.
    residues={k%5:v for k,v in tracks.items()}
    # Any unfilled positions in the period are assigned the nearest known track.
    word=[]
    for i in range(5):
        if i in residues: word.append(residues[i])
        else:
            k=min(residues,key=lambda x:min((x-i)%5,(i-x)%5))
            word.append(residues[k])
    return [[word[(r+c)%5] for c in range(w)] for r in range(h)]
PY

